import { PlaneGeometry, Mesh, MeshBasicNodeMaterial, Texture, Object3D } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Destructure config
  const { textContent, cinematicPrimitives, behavior, scenePosition, sceneRotation, sceneScale } = config;
  const { textureLoader } = ctx;

  // Load brushed metal texture
  const texture = textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  texture.wrapS = texture.wrapT = Texture.RepeatWrapping;

  // Create geometry for the row plane
  const rowWidth = 4.0;
  const rowHeight = 0.4;
  const geometry = new PlaneGeometry(rowWidth, rowHeight);

  // Material with texture
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: 0xffffff,
  });

  const plane = new Mesh(geometry, material);
  plane.castShadow = false;
  plane.receiveShadow = false;

  // Create group to hold the row and additional elements
  const group = new Object3D();
  group.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  group.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  group.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);
  group.add(plane);

  // Add subtle divider at bottom edge
  const dividerHeight = 0.01;
  const dividerY = -rowHeight / 2 + dividerHeight / 2;
  const dividerGeo = new PlaneGeometry(rowWidth, dividerHeight);
  const dividerMat = new MeshBasicNodeMaterial({
    color: 0xe8ecf2, // paper
    transparent: true,
    opacity: 0.3,
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, dividerY, 0.001); // slightly in front to avoid z-fight
  group.add(divider);

  // Store original Y position for hover animation
  let baseY = scenePosition.y;

  // ----- Interactions -----
  const handlers = {};

  // Hover: rise-in by 0.15 units
  handlers.hover = {
    enter: () => {
      gsap.killTweensOf(group.position, 'y');
      gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.3,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    leave: () => {
      gsap.killTweensOf(group.position, 'y');
      gsap.to(group.position, {
        y: baseY,
        duration: 0.3,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
  };

  // Click: press-down and emit event
  handlers.click = () => {
    // Press-down animation
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
      overwrite: 'auto',
    });

    // Emit navigation event if ctx supports it
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-collection.select');
    }
  };

  group.userData.handlers = handlers;

  // ----- Cleanup -----
  group.userData.cleanup = () => {
    gsap.killTweensOf(group);
    gsap.killTweensOf(plane);
    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    // Texture is cached, no dispose needed
  };

  return group;
}
